function processItems(items, callback) {
  if (items.length === 0) {
    callback(null, []);
    return;
  }
  const item = items[0];
  if (computedCache[item]) {
    processItems(items.slice(1), function(err, rest) {
      callback(null, [computedCache[item]].concat(rest));
    });
  } else {
    asyncCompute(item, function(err, result) {
      computedCache[item] = result;
      processItems(items.slice(1), function(err, rest) {
        callback(null, [result].concat(rest));
      });
    });
  }
}

