class DataPoller {
  constructor(interval) {
    this.data = [];
    this.interval = interval;
  }
  start() {
    setTimeout(function() {
      this.data.push(Date.now());
      setTimeout(arguments.callee, this.interval);
    }, this.interval);
  }
}
